import { chromium } from 'playwright';import fs from 'fs';
const BASE='https://www.statesideqm.com',THEME='158900125851',OUT='sep18-sg-count-settle';fs.mkdirSync(OUT,{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();const req=[];p.on('request',r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')req.push(r.url())});
const u=new URL('/collections/state-guard-series-ohio',BASE);u.searchParams.set('preview_theme_id',THEME);const resp=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});
const snap=async phase=>p.evaluate(phase=>({phase,cards:[...document.querySelectorAll('.sqsg-card')].map(a=>({label:(a.querySelector('strong')?.textContent||'').trim(),meta:(a.querySelector('small')?.textContent||'').trim(),href:a.getAttribute('href')||''})),view:{...document.querySelector('[data-sqsg-view]')?.dataset},theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')}}),phase);
await p.waitForTimeout(1200);const early=await snap('early');await p.waitForTimeout(30000);const settled=await snap('settled');const out={http:resp?.status()??null,early,settled,productJson:req.filter(x=>x.includes('/products.json')).length,requests:req};fs.writeFileSync(OUT+'/result.json',JSON.stringify(out,null,2));console.log('SGCOUNTSETTLE',JSON.stringify(out));if(out.http!==200||settled.cards.some(x=>/checking|loading/i.test(x.meta)))process.exitCode=2;await c.close();await b.close();